<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AcademicRepository,AttendanceRepository,EmployeeRepository,SettingsRepository};use App\Services\AttendanceService;use App\Support\Flash;
final class AttendanceController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():AttendanceRepository{return new AttendanceRepository($this->app->database());}private function denied():?Response{return can('attendance.view')?null:Response::html('Forbidden',403);}private function validDate(string$d):bool{$x=\DateTimeImmutable::createFromFormat('Y-m-d',$d);return$x&&$x->format('Y-m-d')===$d;}
public function students(Request$r):Response{if($x=$this->denied())return$x;$date=(string)$r->query('date',date('Y-m-d'));$class=(int)$r->query('class',0);$classes=(new AcademicRepository($this->app->database()))->classes($this->i());$rows=$class&&$this->validDate($date)?$this->r()->students($class,$date,$this->i()):[];return$this->renderPage('attendance-students',['classes'=>$classes,'attendanceRows'=>$rows,'selectedDate'=>$date,'selectedClass'=>$class]);}
public function saveStudents(Request$r):Response{if($x=$this->denied())return$x;$date=(string)$r->input('date');$class=(int)$r->input('class');if(!$this->validDate($date))return Response::html('Invalid attendance date',422);$existing=$this->r()->students($class,$date,$this->i());$ids=array_map(fn($x)=>(int)$x['id'],$existing);if(!$ids)return Response::html('No active students found for this class',422);try{(new AttendanceService($this->r()))->saveStudents($date,$ids,(array)$r->input('status',[]),(array)$r->input('remarks',[]),(int)user()['id']);}catch(\InvalidArgumentException$e){return Response::html(e($e->getMessage()),422);}Flash::add('success','Student attendance saved.');return Response::redirect(url('/admin/attendance/students?date='.$date.'&class='.$class));}
public function employees(Request$r):Response{if($x=$this->denied())return$x;$date=(string)$r->query('date',date('Y-m-d'));$rows=$this->validDate($date)?$this->r()->employees($date,$this->i()):[];return$this->renderPage('attendance-employees',['attendanceRows'=>$rows,'selectedDate'=>$date]);}
public function saveEmployees(Request$r):Response{if($x=$this->denied())return$x;$date=(string)$r->input('date');if(!$this->validDate($date))return Response::html('Invalid attendance date',422);$existing=$this->r()->employees($date,$this->i());$ids=array_map(fn($x)=>(int)$x['id'],$existing);if(!$ids)return Response::html('No active employees found',422);try{(new AttendanceService($this->r()))->saveEmployees($date,$ids,(array)$r->input('status',[]),(array)$r->input('time_in',[]),(array)$r->input('time_out',[]),(array)$r->input('remarks',[]),(int)user()['id']);}catch(\InvalidArgumentException$e){return Response::html(e($e->getMessage()),422);}Flash::add('success','Employee attendance saved.');return Response::redirect(url('/admin/attendance/employees?date='.$date));}
public function classwise(Request$r):Response{if($x=$this->denied())return$x;$date=(string)$r->query('date',date('Y-m-d'));$class=(int)$r->query('class',0);if(!$this->validDate($date))return Response::html('Invalid attendance date',422);if($class&&!(new AcademicRepository($this->app->database()))->classExists($class,$this->i()))return Response::html('Invalid class',422);return$this->renderPage('attendance-classwise',['rows'=>$this->r()->classSummary($this->i(),$date,$class),'classes'=>(new AcademicRepository($this->app->database()))->classes($this->i()),'selectedDate'=>$date,'selectedClass'=>$class]);}
public function studentReport(Request$r):Response{if($x=$this->denied())return$x;$from=(string)$r->query('from',date('Y-m-01'));$to=(string)$r->query('to',date('Y-m-d'));$class=(int)$r->query('class',0);if(!$this->validDate($from)||!$this->validDate($to)||$from>$to)return Response::html('Invalid attendance date range',422);$classes=(new AcademicRepository($this->app->database()))->classes($this->i());return$this->renderPage('attendance-student-report',['rows'=>$this->r()->studentRecords($this->i(),$from,$to,$class),'classes'=>$classes,'from'=>$from,'to'=>$to,'selectedClass'=>$class]);}
public function employeeReport(Request$r):Response{if($x=$this->denied())return$x;$from=(string)$r->query('from',date('Y-m-01'));$to=(string)$r->query('to',date('Y-m-d'));if(!$this->validDate($from)||!$this->validDate($to)||$from>$to)return Response::html('Invalid attendance date range',422);return$this->renderPage('attendance-employee-report',['rows'=>$this->r()->employeeRecords($this->i(),$from,$to),'from'=>$from,'to'=>$to]);}
}
